mapper.select:
SELECT A.CMPNY_CD AS cmpnyCd , A.CMPNY_NM AS cmpnyNm , A.APPLCNT_NM AS applcntNm , A.APPLCNT_EMAIL AS applcntEmail , A.OFFM_TELNO AS offmTelno , A.EXPRTN_YMD AS exprtnYmd , DATE_FORMAT(A.CREATION_DT, '%Y-%m-%d') AS creationDt , C.MESSAGE_CN AS sbscrbSttusNm , A.SBSCRB_STTUS AS sbscrbSttus FROM CM_CMPNY A LEFT JOIN CM_CODE_DETAIL B ON B.CODE_ID = 'CMMNCODE.540' AND B.CMPNY_CD = 'CMMN' AND B.DETAIL_CODE_VALUE = A.SBSCRB_STTUS LEFT JOIN CM_MESSAGE_LANG C ON C.LANG_KEY = B.CODE_LANG_KEY AND C.CMPNY_CD = B.CMPNY_CD AND C.LANG_CODE = #{languageCode} WHERE 1=1
AND A.SBSCRB_STTUS = #{sbscrbSttus}
AND CONCAT(IFNULL(A.CMPNY_CD,''), IFNULL(A.CMPNY_NM,'')) LIKE CONCAT('%', #{searchKeyword}, '%')
ORDER BY A.CREATION_DT DESC LIMIT #{recordCountPerPage} OFFSET #{offset}

SELECT COUNT(*) FROM CM_CMPNY A WHERE 1=1
AND A.SBSCRB_STTUS = #{sbscrbSttus}
AND CONCAT(IFNULL(A.CMPNY_CD,''), IFNULL(A.CMPNY_NM,'')) LIKE CONCAT('%', #{searchKeyword}, '%')
